SELECT p.id AS position_id, o.id, o.status, o.started_at, o.last_evidence_at, o.latest_signal_id, o.evidence_count, o.buy_count, o.watch_count, o.neutral_count, o.bearish_count, o.five_minute_decision, o.one_hour_decision, o.execution_source, o.recommended_position_percent, o.decision_code, LEFT(o.decision_explanation,500) AS explanation, o.executed_at FROM paper_position p JOIN execution_opportunity o ON o.symbol = p.symbol AND o.started_at <= p.opened_at AND o.last_evidence_at >= p.opened_at - INTERVAL 30 MINUTE WHERE p.id IN (104,101,96,91,82,78) ORDER BY p.id, o.id